from itertools import product
from math import comb
from hashlib import sha256

# Partitions are tuples without trailing zeroes.
def pad(p,n): return p+(0,)*(n-len(p))
def size(p): return sum(p)
def contained(a,b):
    n=max(len(a),len(b)); return all(x<=y for x,y in zip(pad(a,n),pad(b,n)))
def parts_box(r,q):
    out=[]
    def rec(last,left,cur):
        if left==0:
            z=tuple(x for x in cur)
            while z and z[-1]==0: z=z[:-1]
            out.append(z); return
        for x in range(last,-1,-1): rec(x,left-1,cur+[x])
    rec(q,r,[])
    return out

# Independent generic LR enumerator.  Cells are processed in the LR reading
# order: rows top-to-bottom and within a row right-to-left.
def lr_coeff(lam,mu,nu):
    if not contained(mu,nu) or size(lam)+size(mu)!=size(nu): return 0
    R=max(len(mu),len(nu)); M=pad(mu,R); N=pad(nu,R)
    cells=[]
    for rr in range(R):
        for cc in range(N[rr],M[rr],-1): cells.append((rr,cc))
    counts=[0]+list(lam); L=len(lam)
    used=[0]*(L+1); fill={}; ans=0
    def go(t):
        nonlocal ans
        if t==len(cells): ans+=1; return
        rr,cc=cells[t]
        right=fill.get((rr,cc+1)); above=fill.get((rr-1,cc))
        for x in range(1,L+1):
            if used[x]>=counts[x]: continue
            # Rows weakly increase left-to-right; columns strictly increase down.
            if right is not None and x>right: continue
            if above is not None and x<=above: continue
            used[x]+=1
            # ballot/Yamanouchi condition on every word prefix
            if all(used[y]>=used[y+1] for y in range(1,L)):
                fill[(rr,cc)]=x; go(t+1); del fill[(rr,cc)]
            used[x]-=1
    go(0); return ans

# Independent Pieri test for h_k=s_(k): nu/mu must be a horizontal k-strip.
def pieri_h(k,mu,nu):
    if not contained(mu,nu) or size(nu)-size(mu)!=k: return 0
    R=max(len(mu),len(nu)); M=pad(mu,R); N=pad(nu,R)
    cols=[]
    for rr in range(R): cols += list(range(M[rr]+1,N[rr]+1))
    return int(len(cols)==k and len(set(cols))==k)

# Integer Smith diagonal by elementary unimodular row/column operations.
def smith_diag(A):
    A=[row[:] for row in A]
    m=len(A); n=len(A[0]) if m else 0; k=0; ds=[]
    while k<m and k<n:
        pos=None
        for i in range(k,m):
            for j in range(k,n):
                if A[i][j] and (pos is None or abs(A[i][j])<abs(A[pos[0]][pos[1]])):
                    pos=(i,j)
        if pos is None: break
        i,j=pos; A[k],A[i]=A[i],A[k]
        for row in A: row[k],row[j]=row[j],row[k]
        while True:
            changed=True
            while changed:
                changed=False
                for i in range(k+1,m):
                    if A[i][k]:
                        q=A[i][k]//A[k][k]
                        A[i]=[A[i][z]-q*A[k][z] for z in range(n)]
                        if abs(A[i][k])<abs(A[k][k]) and A[i][k]:
                            A[k],A[i]=A[i],A[k]
                        changed=True; break
                if changed: continue
                for j in range(k+1,n):
                    if A[k][j]:
                        q=A[k][j]//A[k][k]
                        for row in A: row[j]-=q*row[k]
                        if abs(A[k][j])<abs(A[k][k]) and A[k][j]:
                            for row in A: row[k],row[j]=row[j],row[k]
                        changed=True; break
            bad=None
            p=A[k][k]
            for i in range(k+1,m):
                for j in range(k+1,n):
                    if A[i][j]%p: bad=(i,j); break
                if bad: break
            if bad is None: break
            # Insert the offending entry into pivot row, then Euclidean-reduce again.
            i,j=bad
            A[k]=[A[k][z]+A[i][z] for z in range(n)]
        if A[k][k]<0: A[k]=[-x for x in A[k]]
        ds.append(A[k][k]); k+=1
    return ds

# Required regressions, including the prior padding bug case.
assert lr_coeff((1,1),(1,),(3,))==0
assert lr_coeff((1,1),(2,),(2,2))==0

all_lines=[]; total=0
for r in range(2,6):
  for q in range(2,7):
    if r<=4 and q<=5: continue
    B=parts_box(r,q)
    for i in range(1,q):
      for j in range(1,r):
        rho=(i,)*j
        U=[x for x in B if contained(rho,x)]
        bydeg={}
        for x in U: bydeg.setdefault(size(x),[]).append(x)
        # Relation columns are LR products h_k*s_mu, computed by tableaux.
        rel={d:[] for d in bydeg}
        for mu in U:
          for kk in range(1,q+1):
            d=size(mu)+kk
            if d not in bydeg: continue
            v=[]
            for nu in bydeg[d]:
              a=lr_coeff((kk,),mu,nu)
              b=pieri_h(kk,mu,nu)
              assert a==b, (r,q,i,j,kk,mu,nu,a,b)
              v.append(a)
            if any(v): rel[d].append(v)
        diag=[]; free=0
        for d,rows in bydeg.items():
          # map Z^(relations) -> Z^(partitions): transpose relation vectors
          cols=rel.get(d,[])
          A=[[col[x] for col in cols] for x in range(len(rows))]
          dd=smith_diag(A)
          rank=sum(z!=0 for z in dd); free+=len(rows)-rank
          assert all(z==1 for z in dd), (r,q,i,j,d,dd)
        aa=min(q-i,r-j); bb=min(i,j); N=comb(aa+bb,aa)
        assert free==N, (r,q,i,j,free,N)
        all_lines.append(f'({r},{q};{i},{j}):Z^{free}')
        total+=1
print('REGRESSIONS c_(1,1),(1)^(3)=0; c_(1,1),(2)^(2,2)=0')
print('CASES',total)
print('; '.join(all_lines))
print('SHA256',sha256(('\n'.join(all_lines)).encode()).hexdigest())
